package io.github.jesterportfolio.hearth.survival.housing;
import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class HousingSettingsTest{
 private Properties p(){var p=new Properties();try(var r=Files.newBufferedReader(Path.of("infrastructure/network/housing.properties"))){p.load(r);}catch(Exception e){throw new AssertionError(e);}return p;}
 @Test void sample_is_disabled_and_amounts_are_external(){var s=HousingSettings.parse(p());assertFalse(s.purchases());assertFalse(s.allowNew());assertEquals(List.of(64,128,256,512),s.catalog().tiers().stream().map(HousingSettings.Tier::width).toList());}
 @Test void upgrades_charge_only_difference_and_cannot_shrink(){var c=HousingSettings.parse(p()).catalog();assertEquals(10000,c.cost(-1,0));assertEquals(30000,c.cost(0,1));assertEquals(630000,c.cost(0,3));assertThrows(IllegalArgumentException.class,()->c.cost(2,1));assertThrows(IllegalArgumentException.class,()->c.cost(1,1));}
 @Test void catalog_round_trip_is_exact_and_immutable(){var c=HousingSettings.parse(p()).catalog();assertEquals(c,HousingSettings.Catalog.unpack(c.version(),c.packed()));assertThrows(UnsupportedOperationException.class,()->c.tiers().clear());}
 @Test void changed_price_requires_different_hash_but_not_geometry(){var original=HousingSettings.parse(p());var p=p();p.setProperty("tier.small.price","9000");var other=HousingSettings.parse(p);assertNotEquals(original.catalog().hash(),other.catalog().hash());assertEquals(original.geometryHash(),other.geometryHash());}
 @Test void invalid_or_overlapping_plots_and_spawn_intrusion_are_rejected(){for(var change:List.of(Map.of("plot.first.x","0"),Map.of("plot.second.z","0"),Map.of("plot.first.width","100"),Map.of("plots","first,first"))){var p=p();p.putAll(change);assertThrows(IllegalArgumentException.class,()->HousingSettings.parse(p));}}
 @Test void invalid_price_order_size_and_boolean_are_rejected(){for(var change:List.of(Map.of("tier.small.width","17"),Map.of("tier.medium.width","64"),Map.of("tier.medium.price","10000"),Map.of("allow-new-policy","yes"),Map.of("max-loaded-worlds","0"))){var p=p();p.putAll(change);assertThrows(IllegalArgumentException.class,()->HousingSettings.parse(p));}}
 @Test void geometry_changes_are_fenced_independent_of_capacity_tuning(){var s=HousingSettings.parse(p());var p=p();p.setProperty("plot.first.x","40");assertNotEquals(s.geometryHash(),HousingSettings.parse(p).geometryHash());p=p();p.setProperty("max-loaded-worlds","2");assertEquals(s.geometryHash(),HousingSettings.parse(p).geometryHash());}
}
